import{_ as e,c as t,o as a,a4 as r}from"./chunks/framework.BYxathSa.js";const f=JSON.parse('{"title":"Q4：key 属性的作用及使用注意事项","description":"","frontmatter":{},"headers":[],"relativePath":"react/q4.md","filePath":"react/q4.md","lastUpdated":null}'),o={name:"react/q4.md"},s=r('<h1 id="q4-key-属性的作用及使用注意事项" tabindex="-1">Q4：key 属性的作用及使用注意事项 <a class="header-anchor" href="#q4-key-属性的作用及使用注意事项" aria-label="Permalink to &quot;Q4：key 属性的作用及使用注意事项&quot;">​</a></h1><p><strong>作用</strong>：key 用于标识列表中的每个子元素，帮助 React 在进行 Diff 比较时判断哪些元素可以复用、哪些需要新增或删除。</p><p><strong>不正确的 key 会导致</strong>：</p><ul><li>状态错乱（如输入框内容没有跟随移动）。</li><li>性能下降，DOM 无法复用，产生不必要的销毁和重建。</li></ul><p><strong>使用规则</strong>：</p><ul><li>key 必须是<strong>唯一且稳定</strong>的，通常使用数据的 ID。</li><li>不要使用数组索引 index（除非列表是静态且无排序操作）。</li><li>key 仅在兄弟节点之间需要唯一，不必全局唯一。</li></ul>',6),n=[s];function l(i,_,c,d,p,k){return a(),t("div",null,n)}const h=e(o,[["render",l]]);export{f as __pageData,h as default};
